            while nums[max_dq[0]] - nums[min_dq[0]] > 2:
                l += 1
                if min_dq[0] < l:
                    min_dq.popleft()
                if max_dq[0] < l:
                    max_dq.popleft()
            ans += (r - l + 1)
        return ans
