class Solution {
public:
    long long continuousSubarrays(vector<int>& nums) {
        deque<int> min_dq, max_dq;
        int l = 0;
        long long ans = 0;
        for (int r = 0; r < (int)nums.size(); ++r) {
            int x = nums[r];
            while (!min_dq.empty() && nums[min_dq.back()] >= x) min_dq.pop_back();
            min_dq.push_back(r);
            while (!max_dq.empty() && nums[max_dq.back()] <= x) max_dq.pop_back();
            max_dq.push_back(r);
            while (nums[max_dq.front()] - nums[min_dq.front()] > 2) {
                l++;
                if (min_dq.front() < l) min_dq.pop_front();
                if (max_dq.front() < l) max_dq.pop_front();
            }
            ans += (r - l + 1);
        }
        return ans;
    }
};

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public long continuousSubarrays(int[] nums) {
        Deque<Integer> minDq = new ArrayDeque<>();
        Deque<Integer> maxDq = new ArrayDeque<>();
        int l = 0;
        long ans = 0;
        for (int r = 0; r < nums.length; r++) {
            int x = nums[r];
            while (!minDq.isEmpty() && nums[minDq.peekLast()] >= x) minDq.pollLast();
            minDq.offerLast(r);
            while (!maxDq.isEmpty() && nums[maxDq.peekLast()] <= x) maxDq.pollLast();
            maxDq.offerLast(r);
            while (nums[maxDq.peekFirst()] - nums[minDq.peekFirst()] > 2) {
                l++;
                if (minDq.peekFirst() < l) minDq.pollFirst();
                if (maxDq.peekFirst() < l) maxDq.pollFirst();
            }
            ans += (r - l + 1);
        }
        return ans;
    }
}

